figures.script:
diagram("direction: right
[Producer] as p #mint
[Buffer of N slots] as b #blue
[Consumer] as c #violet
p -> b : wait(empty), wait(mutex), put, signal(mutex), signal(full)
b -> c : wait(full), wait(mutex), get, signal(mutex), signal(empty)
@0 p -> b : item
@1.4 b -> c : item
loop 3.5");
